schemas.schema-05-orders.prisma:
/// Order Entity - Implements core transactional order requirement as per Order Fulfillment & Payments doc. This model captures the complete atomic record for each commercial purchase, including customer linkage and lifecycle status. Compliance with 3NF: all aggregate data handled elsewhere, only atomic fields in this model. Example: Represents a customer's single purchase, splitting by seller if required.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_orders {
