  customer_id String @db.Uuid

  /// Business visible tracking code; unique identifier for user-facing order lookup. Ensures traceability; unique-indexed.
  order_number String

  /// Order status at this state (pending, confirmed, paid, fulfilled, shipped, delivered, cancelled, etc). Atomic (not computed).
  status String

