  /// If the item is part of a bundle: {@link ai_mall_backend_bundles.id} (nullable). Supports per-bundle itemization; null otherwise.
  ai_mall_backend_bundle_id String? @db.Uuid

  /// Atomically tracked number of units for this item in the cart. Direct input, strictly atomic, not a calculated value.
  quantity Int @db.Integer

  /// Timestamp this item was added, for audit and analytics.
  added_at DateTime @db.Timestamptz

  /// Last update timestamp for this item.
  updated_at DateTime @db.Timestamptz

