}

schemas.schema-08-reviews.prisma:
/// Review Entity - Implements the 'Reviews & Comments' and audit requirements from the requirements document. Stores all user-generated product/order reviews and associated metadata, providing core support for the reviews module. Maintains 3NF by isolating reviews from comments, upvotes, and snapshots. Example: Customer writes a review for a purchased product. Key: connects to customer, product/order, comments, upvotes, snapshots.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_reviews {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each review record.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_backend_customers.id}. Identifies which customer wrote the review.
  customer_id String @db.Uuid

  /// Target product's {@link ai_mall_backend_products.id}. Identifies which product the review is about. Nullable if the review is order-scoped only.
  product_id String? @db.Uuid

  /// Related order's {@link ai_mall_backend_orders.id}. Links review directly to an order. Nullable for general product reviews not tied to an order.
  order_id String? @db.Uuid

  /// Review title - Summary of review. Not nullable. E.g., 'Great service!'.
  title String

  /// Review body text - Full content. Not nullable. E.g., 'Shipping was fast and ...'.
  body String

  /// Review rating (1-5 stars, etc). Not nullable. E.g., 4.
  rating Int @db.Integer

  /// Moderation or workflow status. Not nullable. E.g., 'pending', 'published'.
  status String

  /// Creation timestamp. Audit purpose. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp. Not nullable.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Nullable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_reviews_customers ai_mall_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)
  FK_reviews_products ai_mall_backend_products? @relation(fields: [product_id], references: [id], onDelete: Cascade)
  FK_reviews_orders ai_mall_backend_orders? @relation(fields: [order_id], references: [id], onDelete: Cascade)

  ai_mall_backend_review_moderation_logs ai_mall_backend_review_moderation_logs[]
  ai_mall_backend_review_comments ai_mall_backend_review_comments[]
  ai_mall_backend_review_upvotes ai_mall_backend_review_upvotes[]
  ai_mall_backend_review_snapshots ai_mall_backend_review_snapshots[]
  ai_mall_backend_sentiment_analyses ai_mall_backend_sentiment_analyses[]

  @@index([order_id])

  @@unique([customer_id, product_id])
  @@index([status])
  @@index([product_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review Comment Entity - Implements threaded commenting for reviews, supporting threaded responses, moderation, and audit. Linked to customers/sellers as actors via foreign keys. Maintains 3NF by isolating comments from reviews, upvotes, and snapshots. Example: Seller replies to negative review. Key: connects to review, actor, parent comment for threading.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_review_comments {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each review comment.
  id String @id @db.Uuid

  /// Associated review's {@link ai_mall_backend_reviews.id}. The review this comment responds to.
  review_id String @db.Uuid

  /// Actor's {@link ai_mall_backend_customers.id} or {@link ai_mall_backend_sellers.id}. The user or seller who wrote this comment. See documentation for resolving actor domain.
  actor_id String @db.Uuid

  /// Parent comment's {@link ai_mall_backend_review_comments.id} for nesting. Nullable for root.
  parent_id String? @db.Uuid

  /// Comment content text. Not nullable.
  body String

  /// Comment creation time. Not nullable.
  created_at DateTime @db.Timestamptz

  /// Last edit time. Not nullable.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_reviewcomments_reviews ai_mall_backend_reviews @relation(fields: [review_id], references: [id], onDelete: Cascade)
  FK_reviewcomments_actor ai_mall_backend_customers @relation(fields: [actor_id], references: [id], onDelete: Cascade)
  FK_reviewcomments_parent ai_mall_backend_review_comments? @relation("recursive", fields: [parent_id], references: [id], onDelete: Cascade)

  recursive ai_mall_backend_review_comments[] @relation("recursive")
  ai_mall_backend_review_upvotes ai_mall_backend_review_upvotes[]
  ai_mall_backend_sentiment_analyses ai_mall_backend_sentiment_analyses[]

  @@index([actor_id])
  @@index([parent_id])

  @@index([review_id, created_at])
  @@index([body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Review Upvote Entity - Stores upvotes for reviews and comments. Each record ensures unique (actor, review or comment) combination. Maintains 3NF by storing individual upvote events. Example: Customer upvotes helpful comment. Key: references actor, review, or comment. Special: uniqueness constraints enforced.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_review_upvotes {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each upvote.
  id String @id @db.Uuid

  /// Actor's {@link ai_mall_backend_customers.id} or {@link ai_mall_backend_sellers.id}. The actor who upvoted. Domain resolved in application.
  actor_id String @db.Uuid

  /// Review's {@link ai_mall_backend_reviews.id}. Target review, nullable for comment upvotes.
  review_id String? @db.Uuid

  /// Comment's {@link ai_mall_backend_review_comments.id}. Target comment, nullable for review upvotes.
  comment_id String? @db.Uuid

  /// Upvote timestamp. Not nullable.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_reviewupvotes_actor ai_mall_backend_customers @relation(fields: [actor_id], references: [id], onDelete: Cascade)
  FK_reviewupvotes_review ai_mall_backend_reviews? @relation(fields: [review_id], references: [id], onDelete: Cascade)
  FK_reviewupvotes_comment ai_mall_backend_review_comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  @@index([review_id])
  @@index([comment_id])

  @@unique([actor_id, review_id])
  @@unique([actor_id, comment_id])
}

/// Review Snapshot Entity - Captures review version/audit trail. Each change or moderation event creates a snapshot for compliance and dispute resolution. Maintains 3NF. Example: Editing a review creates a before/after snapshot. Key: links review, actor, before/after states. Audit field for moderation reasons.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_review_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each snapshot.
  id String @id @db.Uuid

  /// Target review's {@link ai_mall_backend_reviews.id}.
  review_id String @db.Uuid

  /// Actor's {@link ai_mall_backend_customers.id}, {@link ai_mall_backend_admins.id}. The actor who performed the edit/moderation.
  actor_id String @db.Uuid

  /// Snapshot event timestamp.
  timestamp DateTime @db.Timestamptz

  /// Review title before change. Nullable for initial creation.
  before_title String?

  /// Body before change. Nullable for initial creation.
  before_body String?

  /// Rating before change. Nullable for creation.
  before_rating Int? @db.Integer

  /// Review title after change. Not nullable.
  after_title String

  /// Review body after change. Not nullable.
  after_body String

  /// Rating after change. Not nullable.
  after_rating Int @db.Integer

  /// Reason for moderation/change. Nullable.
  moderation_reason String?

  //----
  // RELATIONS
  //----
  FK_reviewsnapshots_review ai_mall_backend_reviews @relation(fields: [review_id], references: [id], onDelete: Cascade)
  FK_reviewsnapshots_actor ai_mall_backend_customers @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  @@index([actor_id])

  @@index([review_id, timestamp])
  @@index([after_body(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([before_body(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Sentiment Analysis Entity - Stores AI-generated sentiment or authenticity analysis results for reviews and comments. Atomic entry for each (review or comment, analysis type) combination. Maintains 3NF. Used for moderation, workflow, analytics. Key: references review or comment, includes score, type, recommendation, fraud flag, and timestamp.
///
/// @namespace Reviews
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_sentiment_analyses {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique for each sentiment result.
  id String @id @db.Uuid

  /// Target review's {@link ai_mall_backend_reviews.id}. Nullable if comment targeted.
  review_id String? @db.Uuid

  /// Target comment's {@link ai_mall_backend_review_comments.id}. Nullable if review targeted.
  comment_id String? @db.Uuid

  /// Type of analysis (e.g. 'sentiment', 'authenticity'). Not nullable.
  analysis_type String

  /// Score/result (e.g., 0.92 sentiment polarity). Not nullable.
  score Float @db.DoublePrecision

  /// AI workflow recommendation (e.g. 'publish', 'manual review'). Not nullable.
  recommendation String

  /// Detected fraud/bot content. Not nullable.
  fraud_detected Boolean

  /// Analysis completion timestamp. Not nullable.
  analyzed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  FK_sentiment_review ai_mall_backend_reviews? @relation(fields: [review_id], references: [id], onDelete: Cascade)
  FK_sentiment_comment ai_mall_backend_review_comments? @relation(fields: [comment_id], references: [id], onDelete: Cascade)

  @@unique([review_id, analysis_type])
  @@unique([comment_id, analysis_type])
  @@index([analyzed_at])
}

schemas.schema-09-favorites.prisma:
/// Favorites Management Table - This implements the requirement for robust, scalable management of user favorites from the requirements document, specifically 'Favorites Management' in the Favorites & Personalization spec. 
///
/// This model stores the direct relationship where a user marks a product as a favorite, capturing the user's action. Maintains 3NF compliance by keeping only atomic identifiers tying user and product. For example, if a customer favorites a handbag, a row records just that association. 
///
/// Key relationships: references existing ai_mall_backend_customers (user) and ai_mall_backend_products (product).
/// Special behaviors: Each user-product favorite is unique; favorites audits rely on associated snapshot tables. Soft deletion via deleted_at for audit.
///
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_favorites {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each favorite relationship.
  id String @id @db.Uuid

  /// Referenced customer's {@link ai_mall_backend_customers.id}. Links favorite entry to specific user.
  ai_mall_backend_customer_id String @db.Uuid

  /// Referenced product's {@link ai_mall_backend_products.id}. Links favorite to an individual product.
  ai_mall_backend_product_id String @db.Uuid

  /// Timestamp when the favorite was created. Provides audit trail.
  created_at DateTime @db.Timestamptz

  /// Soft delete timestamp. Null if active; set when favorite is un-favored.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  favorites_customer_id_fk ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade)
  favorites_product_id_fk ai_mall_backend_products @relation(fields: [ai_mall_backend_product_id], references: [id], onDelete: Cascade)

  ai_mall_backend_favorite_snapshots ai_mall_backend_favorite_snapshots[]

  @@index([ai_mall_backend_product_id])

  @@unique([ai_mall_backend_customer_id, ai_mall_backend_product_id], map: "ai_mall_backend_favorites_ai_mall_backend_customer_id__6c9e903c")
  @@index([created_at])
}

/// Favorites Snapshot Table - Implements the requirement for historical audit and analytics of user favorite changes, directly mapped from 'Favorites snapshotting for historical analytics and rollback.'
///
/// Stores each change in a user's favorite status, allowing for timeline history, analytics, and restoration. 3NF is maintained by keeping each record atomic and linked to a favorite, user, and product.
///
/// Key relationships: references the favorite, customer, and product for each snapshot.
/// Special behaviors: Created on every change (add/remove). Contains state (active/inactive) at the time of snapshot.
///
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_favorite_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for the snapshot entry.
  id String @id @db.Uuid

  /// References the related favorite record's {@link ai_mall_backend_favorites.id}.
  ai_mall_backend_favorite_id String @db.Uuid

  /// Referenced customer's {@link ai_mall_backend_customers.id}.
  ai_mall_backend_customer_id String @db.Uuid

  /// Referenced product's {@link ai_mall_backend_products.id}.
  ai_mall_backend_product_id String @db.Uuid

  /// Type of change: 'added' or 'removed'. Captures business event for audit analytics.
  change_type String

  /// Timestamp of when the favorite status changed. Maintains snapshot accuracy for timelines/audits.
  changed_at DateTime @db.Timestamptz

  /// Unique identifier for the user or service (customer, admin, or AI agent) who performed the action, for audit traceability.
  snapshot_actor_id String @db.Uuid

  /// Text log of the reason for the snapshot, implements audit trail and rollback context.
  snapshot_reason String?

  //----
  // RELATIONS
  //----
  favorite_snapshots_favorite_id_fk ai_mall_backend_favorites @relation(fields: [ai_mall_backend_favorite_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_fav_6888a4c2")
  favorite_snapshots_customer_id_fk ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_cus_3b81331d")
  favorite_snapshots_product_id_fk ai_mall_backend_products @relation(fields: [ai_mall_backend_product_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_pro_69279a86")

  @@index([ai_mall_backend_customer_id], map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_cus_fa438200")
  @@index([ai_mall_backend_product_id], map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_pro_dada7141")

  @@index([ai_mall_backend_favorite_id, changed_at], map: "ai_mall_backend_favorite_snapshots_ai_mall_backend_fav_7cc26e32")
}

/// User Product Alert Table - Implements requirements for user-configurable product alerts (from 'Alerts & Notifications' in the requirements). Allows users to subscribe to product changes—price drops, promos, etc.
///
/// Each alert is atomic (user, product, type), holding only normalized information (3NF), with customizable trigger and frequency. E.g., a customer signs up for a price drop alert for a shirt in size M.
///
/// Key relationships: User and product references; optional links to AI agent for auto-generated alerts.
/// Special behaviors: Frequency and type dictate notification handling; null last_triggered for never-triggered alerts.
///
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_alerts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for alert configuration.
  id String @id @db.Uuid

  /// Referenced customer's {@link ai_mall_backend_customers.id}.
  ai_mall_backend_customer_id String @db.Uuid

  /// Referenced product's {@link ai_mall_backend_products.id}.
  ai_mall_backend_product_id String @db.Uuid

  /// Optional reference to the AI agent that created or manages the alert, if system/AI-generated. Implements delegated automation.
  ai_mall_backend_ai_agent_id String? @db.Uuid

  /// Type of alert: e.g., 'price_drop', 'restock', 'promo', 'custom'. Implements user alert preferences per requirement.
  alert_type String

  /// Notification frequency: e.g., 'immediate', 'daily', 'weekly', 'threshold'. Defines when the alert is sent.
  frequency String

  /// Whether the alert is currently active. Can be deactivated by user/system.
  is_active Boolean

  /// Last time the alert was triggered. Null if never triggered. Used for digest/summary scheduling.
  last_triggered DateTime? @db.Timestamptz

  /// Timestamp when the alert was created, for audit and user records.
  created_at DateTime @db.Timestamptz

  /// If set, the alert is considered deleted (soft delete for compliance/audit). Null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  alerts_customer_id_fk ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade)
  alerts_product_id_fk ai_mall_backend_products @relation(fields: [ai_mall_backend_product_id], references: [id], onDelete: Cascade)
  alerts_ai_agent_id_fk ai_mall_backend_ai_agents? @relation(fields: [ai_mall_backend_ai_agent_id], references: [id], onDelete: Cascade)

  @@index([ai_mall_backend_product_id])
  @@index([ai_mall_backend_ai_agent_id])

  @@unique([ai_mall_backend_customer_id, ai_mall_backend_product_id, alert_type], map: "ai_mall_backend_alerts_ai_mall_backend_customer_id_ai__cb7210a8")
  @@index([created_at])
}

/// Personalization Profile Table - Implements the core requirements for personalized recommendations and feeds ('Personalization & AI Recommendations').
///
/// Each row contains a user's personalization config and metadata—weightings, preferences, etc.—and atomic, normalized fields (3NF) only. No computed recommendations are stored here (those are in the recommendations table).
///
/// Key relationships: Tied to a single user; may reference AI agent as the tuning system.
/// Special behaviors: Profile versioning and weight adjustments handled in business logic; all extended attributes via JSON config.
///
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_personalization_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique profile identifier.
  id String @id @db.Uuid

  /// Referenced customer's {@link ai_mall_backend_customers.id} - the owner of this profile.
  ai_mall_backend_customer_id String @db.Uuid

  /// Reference to AI agent responsible for generating or tuning the personalization profile. Implements delegated/automated AI personalization management.
  ai_mall_backend_ai_agent_id String? @db.Uuid

  /// JSON string capturing key/value pairs that weight favorites, history, etc. Implements extensibility for user-specific tuning.
  preference_weights_config String?

  /// Timestamp of profile creation for audit/history.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last profile update, for system/business logic use.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  personalization_profiles_customer_id_fk ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_personalization_profiles_ai_mall_backe_13976929")
  personalization_profiles_ai_agent_id_fk ai_mall_backend_ai_agents? @relation(fields: [ai_mall_backend_ai_agent_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_personalization_profiles_ai_mall_backe_a0f9ca1b")

  ai_mall_backend_recommendations ai_mall_backend_recommendations[]

  @@index([ai_mall_backend_ai_agent_id], map: "ai_mall_backend_personalization_profiles_ai_mall_backe_5400a89d")

  @@unique([ai_mall_backend_customer_id], map: "ai_mall_backend_personalization_profiles_ai_mall_backe_9bfe64fa")
  @@index([created_at])
}

/// Recommendations Table - Implements the requirement for AI- or rules-based product recommendations ('Personalization & AI Recommendations').
///
/// Stores each recommended product for each user, the ranking, and context (batch, personalized feed, etc.). 3NF maintained: every record ties only user, product, method, and rank, with no redundant or computed fields.
///
/// Key relationships: Connects each user and product recommended; references optional AI agent generator and personalization profile.
/// Special behaviors: Supports feed regeneration; track historical/batch recommendations; never store calculated scores here.
///
///
/// @namespace Favorites
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_recommendations {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for recommendation row.
  id String @id @db.Uuid

  /// Referenced user's {@link ai_mall_backend_customers.id} - who receives the recommendation.
  ai_mall_backend_customer_id String @db.Uuid

  /// Referenced product's {@link ai_mall_backend_products.id} - the product recommended.
  ai_mall_backend_product_id String @db.Uuid

  /// Reference to the personalization profile (if used for this recommendation).
  ai_mall_backend_personalization_profile_id String? @db.Uuid

  /// Optional reference to AI agent that generated the recommendation.
  ai_mall_backend_ai_agent_id String? @db.Uuid

  /// Type of recommendation, e.g., 'personalized', 'batch', 'ai_suggested', enabling business-side filtering and analytics.
  recommendation_type String

  /// Recommendation ranking/priority. Lower values are higher priority.
  rank Int @db.Integer

  /// Timestamp this recommendation was created. For feed generation and audit.
  created_at DateTime @db.Timestamptz

  /// Optional timestamp after which the recommendation is no longer valid.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  recommendations_customer_id_fk ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_recommendations_ai_mall_backend_custom_792981d7")
  recommendations_product_id_fk ai_mall_backend_products @relation(fields: [ai_mall_backend_product_id], references: [id], onDelete: Cascade)
  recommendations_personalization_profile_id_fk ai_mall_backend_personalization_profiles? @relation(fields: [ai_mall_backend_personalization_profile_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_recommendations_ai_mall_backend_person_da8dc4ef")
  recommendations_ai_agent_id_fk ai_mall_backend_ai_agents? @relation(fields: [ai_mall_backend_ai_agent_id], references: [id], onDelete: Cascade, map: "ai_mall_backend_recommendations_ai_mall_backend_ai_age_2831c761")

  @@index([ai_mall_backend_product_id])
  @@index([ai_mall_backend_personalization_profile_id], map: "ai_mall_backend_recommendations_ai_mall_backend_person_cf647a30")
  @@index([ai_mall_backend_ai_agent_id], map: "ai_mall_backend_recommendations_ai_mall_backend_ai_age_c82e295d")

  @@index([ai_mall_backend_customer_id, created_at], map: "ai_mall_backend_recommendations_ai_mall_backend_custom_6e6f9302")
}

schemas.schema-10-architecture.prisma:
/// System-wide audit log for tracking sensitive or high-value actions and changes, as required by security and compliance requirements from the Architecture, Security, and Compliance documents. This table implements the evidence and immutability protocols, providing an authoritative record of who did what and when. Maintains full 3NF normalization by isolating audit records from business and transaction data. For example, every privileged API call, admin action, or automated AI-triggered event inserts one row, preserving actor, action, and context. Key relationships: May reference actors or affected entities (from other schemas) but contains only logging context. Special behaviors: Should be append-only for audit integrity.
///
/// @namespace Architecture
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_audit_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Serves as the unique identifier for each audit log entry; enables unambiguous referencing in compliance workflows.
  id String @id @db.Uuid

  /// Related actor's {@link ai_mall_backend_admins.id}, {@link ai_mall_backend_sellers.id}, {@link ai_mall_backend_customers.id}, or {@link ai_mall_backend_ai_agents.id} depending on who took the action. Implements actor traceability for each audit record; supports RBAC requirements.
  performed_by_id String @db.Uuid

  /// Type of audited action. Implements audit policy mapping by recording specific action category (e.g., 'login', 'config_change', 'privileged_command'). For example, 'seller_login', 'order_refund', 'api_key_regened', etc.
  action_type String

  /// Table or entity affected by the action, if applicable. Captures business context without denormalizing target data. For example, 'ai_mall_backend_products'.
  target_table String?

  /// ID of the target entity affected. Null if log does not refer to a specific entity. Maintains normalization by not duplicating entity data, only holding reference.
  target_id String? @db.Uuid

  /// Human-readable or structured JSON description of the event for investigation purposes. Ensures no non-atomic data is stored (free text, not aggregated). For example: 'Changed pricing rule X'.
  details String?

  /// Timestamp when the log entry was created. Implements immutable evidence requirement; supports temporal queries and compliance reporting.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_audit_performed_by_id ai_mall_backend_admins @relation(fields: [performed_by_id], references: [id], onDelete: Cascade)

  @@index([performed_by_id, created_at])
  @@index([action_type])
  @@index([details(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Asynchronous, append-only event log for system-level or cross-domain events. Implements the event-driven architecture objective from the Architecture & Extensibility spec—captures all significant business events (e.g., order placed, stock updated, review posted) for use by bus consumers, integrations, and microservices. Maintains normalization by storing only atomic event metadata and business context, never duplicating data from source tables. Usage examples: inserts align with system triggers; consumers process events according to type and payload. Key relationships: no direct foreign keys, as source models reside in other schemas. Special behaviors: typically read-only except for system writes; can be purged according to retention policy.
///
/// @namespace Architecture
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_event_logs {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique event log sequence; provides idempotency and cross-system traceability.
  id String @id @db.Uuid

  /// Event type code (e.g., 'order_placed', 'inventory_updated', 'user_banned'). Implements contract for event consumers/handlers. Strictly atomic, never pre-calculated.
  event_type String

  /// JSON or serialized string containing event parameters (business-context details). Provides contract for event consumers to process payload. Never denormalized; event context only.
  event_payload String

  /// ID for the actor (system, admin, or AI-agent) that emitted the event. Supports auditability and access control workflows. Can be null for pure system events.
  raised_by_id String? @db.Uuid

  /// Timestamp of event emission. Ensures sequenced, temporal event analytics and replay in architecture modules.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  @@index([event_type, created_at])
  @@index([event_payload(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// API or integration key registry and management, as required for onboarding new channels/services per the Architecture Extensibility spec. Each entry maintains key metadata, access scope, and lifecycle status. Fulfills key security, onboarding, and audit requirements—keeps keys isolated, atomic, and never associates secrets or metadata with unrelated business data (3NF compliance). For example, admins or automated routines insert keys for new 3rd-party integrations or internal feature launches. Key relationships: May reference actor/admin IDs from other schemas. Special behaviors: Rotatable, status managed, and strictly not joined to usage logs (which are separate).
///
/// @namespace Architecture
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_integration_keys {
  //----
  // COLUMNS
  //----
  /// Primary Key. Each integration key’s unique ID, guaranteeing unambiguous management and referencing.
  id String @id @db.Uuid

  /// Actor/admin who registered the key. Foreign key to {@link ai_mall_backend_admins.id} in actors domain. Required for traceability and audit policy compliance.
  registered_by_id String @db.Uuid

  /// Opaque API or integration key (stored hashed where possible). Implements credential management without ever storing business or user data here (security/3NF rules). For example, random 32+ char string.
  key_value String

  /// Scope or permitted role of this key (e.g., 'channel_read', 'admin_api_access', 'webhook_consume'). Satisfies principle of least privilege and scope mapping in the extensibility framework. For example: 'system_admin', 'inventory_update'.
  scope String

  /// Lifecycle status for the key (e.g., 'active', 'revoked', 'pending'). Fulfills security, compliance, and automation needs for rotation and auditing. Not nullable to preserve key integrity.
  status String

  /// Timestamp when key was issued/enabled. Used for rotation, expiration, and audit queries. Never derived or pre-calculated.
  issued_at DateTime @db.Timestamptz

  /// (Optional) expiry of the integration key for forced rotation. Maintains access hygiene. Null if perpetual/managed externally.
  expires_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_integrationkey_registered_by_id ai_mall_backend_admins @relation(fields: [registered_by_id], references: [id], onDelete: Cascade)

  @@unique([key_value])
  @@index([scope])
  @@index([registered_by_id, issued_at])
}

/// Register of all deployed API versions/endpoints as required by the API Gateway and Versioning section in the Architecture overview. Supports backward compatibility, extensibility, security compliance, and channel-specific routing. Maintains normalization by logging only atomic version and channel information, never copy-pasting endpoint metadata. Examples: create entry for each version published/deprecated. Key relationships: channel_id references a channel record in the systematic schema. Special behaviors: referenced by routing modules; enables compatibility mapping.
///
/// @namespace Architecture
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_api_versions {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique API version entry, for API registry integrity and routing.
  id String @id @db.Uuid

  /// Reference to {@link ai_mall_backend_channels.id}; identifies the logical or physical channel this version applies to. Critical for proper API mapping and restrictions.
  channel_id String @db.Uuid

  /// Semantic version or identifier (e.g., 'v1', 'v2.1-beta', or full semver '2.3.0'). Fulfills API versioning requirements for documentation, routing, and compatibility. Always atomic.
  version_string String

  /// Date/time of deployment. Used for compatibility audits, rollout monitoring, and routing decisions. Atomic and never pre-calculated.
  deployed_at DateTime @db.Timestamptz

  /// Time at which this version was deprecated. Null if currently active. Maintains compatibility delineation without denormalized status indicators.
  deprecated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_apiversion_channel_id ai_mall_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  @@unique([channel_id, version_string])
  @@index([deployed_at])
}

