schemas.schema-05-orders.prisma:
/// Order Entity - Implements core transactional order requirement as per Order Fulfillment & Payments doc. This model captures the complete atomic record for each commercial purchase, including customer linkage and lifecycle status. Compliance with 3NF: all aggregate data handled elsewhere, only atomic fields in this model. Example: Represents a customer's single purchase, splitting by seller if required.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_orders {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique order identifier.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_backend_customers.id}. Each order tracks its customer for access and audit.
  customer_id String @db.Uuid

  /// Business visible tracking code; unique identifier for user-facing order lookup. Ensures traceability; unique-indexed.
  order_number String

  /// Order status at this state (pending, confirmed, paid, fulfilled, shipped, delivered, cancelled, etc). Atomic (not computed).
  status String

  /// Timestamp for order creation, for audit trail and workflow.
  created_at DateTime @db.Timestamptz

  /// Last order record update. Supports audit logging and temporal queries.
  updated_at DateTime @db.Timestamptz

  /// Soft delete field for retention policies. Null if active.
  deleted_at DateTime? @db.Timestamptz

  /// Optional note/comment from customer for order. Atomic data only.
  note String?

  //----
  // RELATIONS
  //----
  customer ai_mall_backend_customers @relation(fields: [customer_id], references: [id], onDelete: Cascade)

  ai_mall_backend_order_items       ai_mall_backend_order_items[]
  ai_mall_backend_order_status_logs ai_mall_backend_order_status_logs[]
  ai_mall_backend_shipments         ai_mall_backend_shipments[]
  ai_mall_backend_payments          ai_mall_backend_payments[]
  ai_mall_backend_order_snapshots   ai_mall_backend_order_snapshots[]
  ai_mall_backend_coupon_usages     ai_mall_backend_coupon_usages[]
  ai_mall_backend_point_usages      ai_mall_backend_point_usages[]
  ai_mall_backend_inquiries         ai_mall_backend_inquiries[]
  ai_mall_backend_reviews           ai_mall_backend_reviews[]

  @@unique([order_number])
  @@index([customer_id, created_at])
}

/// Order Item - Captures each individual product/variant included in an order, per line, according to Order Fulfillment requirements. Strictly normalized: stores item, product, and unit price at the time of purchase. Multivendor support: links to seller. Each record immutable beyond cancellation/returns. Example: An order for two products, each with a variant, will have two associated records here.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_order_items {
  //----
  // COLUMNS
  //----
