  variant_id String? @db.Uuid

  /// Quantity of this SKU for this order line. Normalized: totals/calculations done externally.
  quantity Int @db.Integer

  /// Unit price at purchase (historically tracked here, no aggregation).
  price Float @db.DoublePrecision

  /// Belonged seller's {@link ai_mall_backend_sellers.id}. References who fulfills this line item.
  seller_id String @db.Uuid

  /// Product name at time of order (snapshot, not FK). For past accuracy even after catalog/title changes.
  title String

  /// Optional per-item customer note (gift messages etc).
  note String?

  //----
  // RELATIONS
